CREATE SCHEMA IF NOT EXISTS clearledger;
CREATE TABLE IF NOT EXISTS clearledger.settlements (settlement_id UUID PRIMARY KEY, account_id TEXT NOT NULL, reference TEXT NOT NULL, debit_party TEXT NOT NULL, credit_party TEXT NOT NULL, current_status TEXT NOT NULL, current_stage TEXT NOT NULL, last_entry_id UUID NULL, last_memo TEXT, version INTEGER NOT NULL, entry_count INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS clearledger.events (seq BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL UNIQUE, settlement_id UUID NOT NULL REFERENCES clearledger.settlements(settlement_id) ON DELETE CASCADE, aggregate_version INTEGER NOT NULL, event_type TEXT NOT NULL, correlation_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE (settlement_id, aggregate_version), UNIQUE(settlement_id, idempotency_key));
CREATE TABLE IF NOT EXISTS clearledger.outbox (seq BIGSERIAL PRIMARY KEY, event_id UUID NOT NULL UNIQUE REFERENCES clearledger.events(event_id) ON DELETE CASCADE, settlement_id UUID NOT NULL REFERENCES clearledger.settlements(settlement_id) ON DELETE CASCADE, aggregate_version INTEGER NOT NULL, correlation_id TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), published_at TIMESTAMPTZ, archived_at TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT);
CREATE TABLE IF NOT EXISTS clearledger.idempotency_keys (scope TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, status_code INTEGER NOT NULL, response_body JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (scope, idempotency_key));
