CREATE OR REPLACE FUNCTION clearledger.noop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
CREATE OR REPLACE TRIGGER t_s BEFORE UPDATE ON clearledger.settlements FOR EACH ROW EXECUTE FUNCTION clearledger.noop();
CREATE OR REPLACE TRIGGER t_e BEFORE UPDATE ON clearledger.events FOR EACH ROW EXECUTE FUNCTION clearledger.noop();
CREATE OR REPLACE TRIGGER t_o BEFORE UPDATE ON clearledger.outbox FOR EACH ROW EXECUTE FUNCTION clearledger.noop();
CREATE OR REPLACE TRIGGER t_i BEFORE UPDATE ON clearledger.idempotency_keys FOR EACH ROW EXECUTE FUNCTION clearledger.noop();
EOF
