                        try:
                            ecs.stop_task(cluster=arn, task=t, reason="clearledger teardown")
                        except Exception:  # noqa: BLE001
                            pass
            except Exception:  # noqa: BLE001
                pass
            for _ in range(20):
                if attempt(f"ecs cluster {name}", ecs.delete_cluster, cluster=arn):
                    break
